        async function loadWorkflowContacts(force=false,{background=false}={}){
            if(!campaignId){setPeopleStatusBadge(); return;}
            if(workflowContactsRequest&&!force) return;
            if(background&&workflowContactActionKey) return;
            workflowContactsRequest?.abort();
            const controller=new AbortController();
            workflowContactsRequest=controller;
            const timeout=setTimeout(function(){controller.abort();},20000);
            let contactsChanged=false, errorCleared=false;
            if(!background){
                workflowContactsLoading=true;
                workflowContactsError='';
                setPeopleStatusBadge();
                if(peopleModalBackdrop?.classList.contains('open')) renderPeopleModal();
            }
            try{
                const encoded=encodeURIComponent(campaignId);
                const payload=await api.request('/campaigns/workflow/attached?campaign_id='+encoded+'&id='+encoded,{signal:controller.signal,cache:'no-store'});
                if(workflowContactsRequest!==controller||controller.signal.aborted) return;
                const contacts=extractWorkflowContacts(payload).map(normalizeWorkflowContact).filter(function(contact){return contact.currentNodeId||contact.participantId||contact.userId||contact.linkedinUrl||contact.name;});
                contactsChanged=JSON.stringify(contacts)!==JSON.stringify(workflowContacts);
                workflowContacts=contacts;
                rebuildWorkflowContactsIndex();
                errorCleared=!!workflowContactsError;
                workflowContactsError='';
            }catch(error){
                // A failed background check leaves the last known participant positions visible.
                if(workflowContactsRequest===controller&&!background) workflowContactsError=error.message||'Could not load people for this workflow.';
            }finally{
                clearTimeout(timeout);
                if(workflowContactsRequest===controller){
                    workflowContactsRequest=null;
                    workflowContactsLoading=false;
                    setPeopleStatusBadge();
                    if(contactsChanged) refreshWorkflowContactBadges();
                    if((contactsChanged||errorCleared||!background)&&peopleModalBackdrop?.classList.contains('open')){
                        const scrollTop=peopleModalBody.scrollTop;
                        renderPeopleModal();
                        peopleModalBody.scrollTop=scrollTop;
                    }
                }
            }
        }
