                const payload=await api.request('/pipeline/list');
                const source=Array.isArray(payload)?payload:(Array.isArray(payload?.data)?payload.data:[]);
                leadLists=source.map(normalizeLeadList).filter(item=>item.id);
                leadListsLoaded=true;
                leadListModalStatus.hidden=true;
            }catch(error){
                leadLists=[];
