            if(isCrmNodeType(type)) return [{value:'not_matched',label:'If Unique Identifier did not Match'},{value:'matched',label:'If Unique Identifier Matched'}];
            if(type==='connect') return [{value:'if_accepted',label:'If Accepted'},{value:'not_accepted',label:'Pending Accept'}];
            if(type==='if_else') return [{value:'if_true',label:'Do A'},{value:'if_false',label:'Do B'}];
            if(type==='icp_screening') return [{value:'icp_match',label:'Match'},{value:'no_icp_match',label:'No Match'}];
