        function handleAddNode(type){
            if(!selectedNodeId) return;
            const selectedNode=getNodeById(selectedNodeId);
            if(!selectedNode) return;
            const insertableEdges=getInsertableOutgoingEdges(selectedNodeId);
            if(insertableEdges.length===0){
                addNode(type,selectedNodeId);
                finishAddNodeFlowAfterInsert();
                return;
            }
            if(insertableEdges.length===1){
                if(isDecisionType(type)){
                    openDecisionContinueModal(type,selectedNodeId,insertableEdges[0].id);
                    return;
                }
                addNode(type,selectedNodeId,insertableEdges[0].id);
                finishAddNodeFlowAfterInsert();
                return;
            }
