        document.getElementById('closeDecisionContinueModal').onclick=function(){pendingDecisionContinueType=null; pendingDecisionContinueParentId=null; pendingDecisionContinueEdgeId=null; closeModal(decisionContinueModalBackdrop);}; document.getElementById('cancelDecisionContinueModal').onclick=function(){pendingDecisionContinueType=null; pendingDecisionContinueParentId=null; pendingDecisionContinueEdgeId=null; closeModal(decisionContinueModalBackdrop);}; document.getElementById('saveDecisionContinueModal').onclick=function(){if(!pendingDecisionContinueType || !pendingDecisionContinueParentId) return; const type=pendingDecisionContinueType; const parentId=pendingDecisionContinueParentId; const edgeId=pendingDecisionContinueEdgeId; const continueBranchKey=decisionContinueSelect.value||''; pendingDecisionContinueType=null; pendingDecisionContinueParentId=null; pendingDecisionContinueEdgeId=null; closeModal(decisionContinueModalBackdrop); addNode(type,parentId,edgeId,continueBranchKey); finishAddNodeFlowAfterInsert();};
        undoDisconnectBtn.addEventListener('click',undoDisconnectEdge);
        dashboardLeadModalFrame.addEventListener('load',function(){if(!dashboardLeadModal.hidden) dashboardLeadModal.classList.remove('loading');});
        window.addEventListener('message',function(event){if(event.origin!==window.location.origin||event.source!==dashboardLeadModalFrame.contentWindow) return; if(event.data&&event.data.type==='coherta-lead-modal-close') closeDashboardLeadModal();});
        document.addEventListener('keydown',function(event){if(ftue.active||window.CohertaScreeningResults.isOpen()) return; const active=document.activeElement; const tag=active&&active.tagName?active.tagName.toLowerCase():''; if(event.code==='Space'&&!['input','textarea','select','button'].includes(tag)){spacePressed=true; event.preventDefault();} if((event.key==='Delete'||event.key==='Backspace') && selectedNodeId && !['input','textarea','select'].includes(tag)){event.preventDefault(); deleteNode(selectedNodeId);}});
        document.addEventListener('keyup',function(event){if(event.code==='Space') spacePressed=false;}); window.addEventListener('blur',function(){spacePressed=false;});
        document.addEventListener('keydown',handleWorkflowClipboardShortcut);
        document.addEventListener('click',function(event){if(!ftue.active) return; if(isFtueClickable(event.target) || event.target.closest('.ftue-card')) return; event.preventDefault(); event.stopPropagation();}, true);
